def model(cid, name, ts=None):
    d = DELTA[cid]
    if name == "@ts":
        return ts + d[0]
    a = int(name.split("_")[1], 16)
    g = 0 if name.startswith("func") else 1 if a < 0x01B01000 else 2 if a < 0x01B07000 else 3
    return None if d[g] is None else a + d[g]


