DATA_BASES = ("D_01B00568", "D_01B00578", "D_01B00598", "D_01B005A0")


def unit(tu, first=None, last=None, extra=DATA_BASES):
    rank, funcs, cids, exc, names = TUS[tu]
    first = funcs[0][0] if first is None else first
    last = funcs[-1][0] if last is None else last
    sel = [(a, z) for a, z in funcs if first <= a <= last]
    assert sel and sel[0][0] == first and sel[-1][0] == last, (hex(tu), hex(first), hex(last))
    size = sel[-1][0] + sel[-1][1] - first  # the object .text is not padded at its end
    layouts = []
    for cid in cids:
        e = exc.get(cid, {})
        ts = e.get("@ts", model(cid, "@ts", tu)) + (first - tu)
        syms = {}
        for n in list(names) + list(extra):
            v = e.get(n, model(cid, n))
            if v is not None:
                syms[n] = v
        layouts.append({"cid": cid, "text_start": ts, "text_end": ts + size, "syms": syms})
    return {
        "src": f"overlays/group11/ovl_09053_f3_{first:08x}.c",
        "containers": cids,
        "text_start": layouts[0]["text_start"],
        "text_end": layouts[0]["text_end"],
        "discovered_code_bytes": sum(z for a, z in sel),
        "functions": len(sel),
        "syms": layouts[0]["syms"],
        "container_layouts": layouts,
    }


